// Substitute __PROJECTION_FIXTURE__ with projection-fixture.json generated by
// scripts/mlrank-resident-projection-check.mjs. Install qkv.safetensors in files/models.
async page => {
    const fixture=__PROJECTION_FIXTURE__;
    return page.evaluate(async f=>{
        const send=async request=>{const id=crypto.randomUUID();await window.Capacitor.nativePromise('RamGpu','submit',{id,payload:JSON.stringify(request)});const result=await fetch('/__rank_ml_result?id='+id).then(r=>r.json());if(result.error)throw Error(result.error);return result;};
        const stat=await fetch('/__rank_model_file?name=qkv.safetensors&action=stat').then(r=>r.json());
        const descriptor={path:'qkv.safetensors',revision:stat.revision,fileSize:f.fileSize,offset:f.headerBytes,length:f.weightBytes,dtype:'F32',shape:[768,2304]};
        let modelId,maxError=0;const profiles=[];
        const load=async()=>{const r=await send({action:'load',model:f.model,inputSizes:f.inputSizes});modelId=r.modelId;};
        const invoke=async index=>{
            const {output,...profile}=await send({action:'invoke',modelId,input:f.xs[index],inputFiles:[null,descriptor],profile:true});
            if(output.length!==2304)throw Error('Wrong output length');
            output.forEach((v,i)=>{const error=Math.abs(v-f.expected[index][i]);maxError=Math.max(maxError,error);if(error>1e-4+Math.abs(f.expected[index][i])*1e-4)throw Error('Numerical mismatch '+i);});
            profiles.push(profile);
        };
        try {
            await load();for(const i of [0,1,0])await invoke(i);
            if(profiles[0].fileBytesRead!==f.weightBytes||profiles[1].fileBytesRead!==0||profiles[2].fileInputsReused!==1)throw Error('Weights not reused');
            let rejected=false;
            try{await send({action:'invoke',modelId,input:f.xs[0],inputFiles:[null,{...descriptor,revision:'stale'}]});}catch(error){if(!String(error).includes('changed'))throw error;rejected=true;}
            if(!rejected)throw Error('Stale descriptor accepted');
            await invoke(1);if(profiles.at(-1).fileBytesRead!==0)throw Error('Unexpected reload');
            await send({action:'release',modelId});await load();await invoke(0);
            if(profiles.at(-1).fileBytesRead!==f.weightBytes)throw Error('Reload reused released input');
            return {weightBytes:f.weightBytes,weightSha256:f.sha256,maxError,valuesCompared:2304*5,staleRejected:true,reloadReadsWeights:true,profiles};
        }finally{if(modelId)await send({action:'release',modelId});}
    },fixture);
}
